/* Material didático autoral recuperado da Teca Academia 2.0. Conteúdo introdutório, não substitui lei ou edital. */
window.TECA_LESSONS=[{"id":"u4","cat":"Português","title":"Interpretação: o texto diz ou você imagina?","question":"De “Muitos cidadãos usam o serviço digital”, conclui-se que:","options":["Todos usam","Ninguém usa","Uma parcela usa","É obrigatório usar"],"answer":2,"why":"“Muitos” indica uma parcela, não a totalidade.","principle":"Leia a pergunta antes do texto. Separe fatos expressos (estão escritos) e inferências (conclusões autorizadas pelas pistas). Em questões de Vunesp, desconfie de “sempre”, “nunca”, “somente” quando o texto diz algo mais moderado.","context":"Um texto é uma fotografia: responda ao que aparece nela, não ao que gostaria que aparecesse.","example":"Texto: “Alguns servidores trabalham remotamente.” É correto dizer que pelo menos alguns trabalham remotamente; não é correto dizer que todos trabalham assim.","pitfall":"Não confunda opinião pessoal com interpretação textual.","reference":""},{"id":"u5","cat":"Português","title":"Tema, tese e argumento","question":"Qual trecho é uma tese?","options":["“Mobilidade urbana.”","“As cidades têm ruas.”","“Deveríamos ampliar o transporte coletivo.”","“Ônibus e metrô.”"],"answer":2,"why":"A tese sustenta uma posição que pode ser defendida.","principle":"Se o texto fala de trabalho remoto, esse é o tema. Se o autor diz “trabalho remoto melhora a produtividade”, essa é a tese. Um dado de redução de tempo de transporte usado para justificar a ideia é um argumento.","context":"Tema é o assunto da conversa; tese é o que alguém defende; argumento é a razão usada.","example":"Tema: transporte urbano. Tese: ônibus mais frequentes reduzem espera. Argumento: intervalos menores entre viagens.","pitfall":"Uma frase sobre o tema pode não revelar a opinião do autor.","reference":""},{"id":"u6","cat":"Português","title":"Conectivos: as pontes do pensamento","question":"“Embora estivesse cansada, estudou.” Expressa:","options":["Causa","Concessão","Finalidade","Tempo"],"answer":1,"why":"Há uma dificuldade admitida, sem impedir a ação.","principle":"Causa: porque, visto que. Consequência: portanto, por isso. Oposição: porém, contudo. Concessão: embora, ainda que. Condição: se, caso. Finalidade: para que. Essas relações aparecem tanto em interpretação quanto em gramática.","context":"Conectivos são plaquinhas na estrada: “mas” faz curva; “porque” explica motivo.","example":"“Embora chovesse, compareceu”: algo poderia dificultar a ida, mas não impediu.","pitfall":"“Embora” não é sinônimo de “porque”.","reference":""},{"id":"u7","cat":"Português","title":"Coesão: quem é “ele”?","question":"Em “Ana revisou o texto e o enviou”, “o” retoma:","options":["Ana","Texto","Revisão","Envio"],"answer":1,"why":"O pronome substitui “texto”.","principle":"Pronomes e expressões substituem ideias anteriores: “Maria entregou o documento. Ela o assinou.” Ela = Maria; o = documento. Às vezes, “isso” retoma uma oração inteira. Volte ao trecho anterior e confira a concordância e o sentido.","context":"Coesão é o barbante que prende frases e referências.","example":"“O processo foi suspenso. Isso surpreendeu a equipe.” “Isso” retoma o fato de a suspensão ocorrer.","pitfall":"O antecedente nem sempre é o substantivo mais próximo: contexto importa.","reference":""},{"id":"u8","cat":"Português","title":"Sentido literal e figurado","question":"“Explicação concisa” é uma explicação:","options":["Breve e clara","Confusa","Contraditória","Sem conteúdo"],"answer":0,"why":"Conciso significa breve, objetivo.","principle":"“A porta fechou” é literal. “A decisão abriu portas” é figurado: criou oportunidades. A banca pode cobrar sentido contextual, sinônimos e antônimos; substitua a palavra mentalmente na frase completa.","context":"Palavra literal veste roupa comum; figurada usa fantasia para comunicar outra ideia.","example":"“Um parecer enxuto” normalmente significa um parecer conciso, não magro.","pitfall":"Sinônimos perfeitos são raros; o contexto define a melhor substituição.","reference":""},{"id":"u9","cat":"Português","title":"Concordância: quem combina com quem?","question":"Qual está correta?","options":["Houveram problemas","Fazem cinco dias","Existem processos pendentes","Devem haver processos"],"answer":2,"why":"“Existem” concorda com “processos”; as demais usam impessoais indevidamente.","principle":"O verbo “existir” concorda: “Existem dúvidas”. “Haver” no sentido de existir é impessoal: “Há dúvidas” (não “haviam dúvidas”). “Fazer” indicando tempo transcorrido também fica no singular: “Faz três anos”.","context":"Sujeito e verbo dançam em dupla: singular com singular, plural com plural.","example":"“Devem existir recursos”, mas “Deve haver recursos”.","pitfall":"O auxiliar de “haver” impessoal também fica no singular.","reference":""},{"id":"u10","cat":"Português","title":"Crase sem desespero","question":"Qual frase exige crase?","options":["Vou a estudar","Cheguei à audiência","Entreguei a ela","A partir de hoje"],"answer":1,"why":"Chegar a + a audiência = à audiência.","principle":"Teste simples: troque a palavra feminina por masculina. Se “à” virar “ao”, há boa indicação de crase. “Fui à secretaria” → “Fui ao cartório”. Antes de verbo, em regra, não ocorre crase: “Começou a estudar”.","context":"Crase é a união de dois “a”: preposição + artigo feminino.","example":"“Entregou a documentação à diretora.” = entregou ao diretor.","pitfall":"Nem toda palavra feminina recebe crase: o verbo anterior precisa pedir preposição “a”.","reference":""},{"id":"u11","cat":"Português","title":"Pontuação: a vírgula muda o sentido","question":"Qual tem vírgula bem empregada?","options":["Os servidores, chegaram cedo","Na audiência, todos ficaram atentos","O juiz, decidiu","A sentença, foi publicada"],"answer":1,"why":"A expressão adverbial antecipada pode ser separada por vírgula.","principle":"Evite separar sujeito do verbo: “Os servidores do setor chegaram”. Use vírgulas para vocativo, enumerações e expressões deslocadas: “Na segunda-feira, o tribunal abriu”. Orações explicativas também podem vir isoladas.","context":"Vírgula não é pausa de respiração; ela organiza pedaços da oração.","example":"“Vamos comer, crianças” chama as crianças; “vamos comer crianças” sugere outra coisa.","pitfall":"Não coloque vírgula automaticamente antes de todo “e”.","reference":""},{"id":"u12","cat":"Português","title":"Regência e pronomes","question":"Qual está adequada?","options":["Prefiro mais café do que chá","Obedeci à orientação","Não avisaram-me","Assisti o filme (no sentido de ver)"],"answer":1,"why":"Obedecer exige a preposição “a”, somada ao artigo “a”.","principle":"“Assistir ao filme” (ver); “obedecer à norma”; “preferir X a Y”. Colocação pronominal: palavras negativas atraem o pronome para antes do verbo: “Não me avisaram”. Observe sempre o sentido do verbo.","context":"Alguns verbos “pedem” preposições, como uma chave pede determinada fechadura.","example":"“Não se deve divulgar o documento” tem pronome antes do verbo por causa de “não”.","pitfall":"Não use a linguagem cotidiana como única referência: a prova cobra norma-padrão.","reference":""},{"id":"u13","cat":"Direito","title":"O que é Direito? Um jogo com regras","question":"A regra sobre a forma de apresentar recurso pertence principalmente ao:","options":["Direito Penal","Direito Processual","Direito Tributário","Direito do Consumidor"],"answer":1,"why":"Recurso é mecanismo do processo, logo tem natureza processual.","principle":"Direito Constitucional define as regras maiores do Estado; Administrativo explica como a administração atua; Penal identifica crimes e penas; Processual descreve o caminho do processo. Leis internas do TJ regulam rotinas da instituição.","context":"Pense numa escola: existem regras, quem decide conflitos e quem faz cumprir decisões.","example":"Se alguém comete um crime contra a Administração: Penal descreve o delito; Processo Penal cuida da apuração e julgamento.","pitfall":"“Direito Penal” e “Processo Penal” não são a mesma disciplina.","reference":""},{"id":"u14","cat":"Direito","title":"Constituição: o livro das regras maiores","question":"A Constituição está:","options":["Abaixo das portarias","No topo da ordem jurídica nacional","No mesmo nível do regulamento interno","Abaixo de lei municipal"],"answer":1,"why":"É o fundamento normativo superior para as demais normas.","principle":"A Constituição trata de direitos fundamentais, organização do Estado, poderes e administração pública. O edital cobra partes determinadas: direitos e garantias individuais e coletivos, direitos sociais, nacionalidade, Administração Pública (arts. 37 a 41) e art. 92.","context":"É o “manual principal” que orienta as outras leis.","example":"Uma lei ordinária não pode contrariar o texto constitucional.","pitfall":"Estude os artigos indicados no edital, não só resumos soltos.","reference":""},{"id":"u15","cat":"Direito","title":"LIMPE: os cinco cuidados da Administração","question":"Ocultar um ato para impedir fiscalização atinge principalmente:","options":["Eficiência","Publicidade","Continuidade","Hierarquia"],"answer":1,"why":"O núcleo do problema é impedir transparência.","principle":"Legalidade: servidor segue autorização legal. Impessoalidade: não favorece amigos. Moralidade: conduta ética. Publicidade: transparência, com exceções legais. Eficiência: serviço com qualidade e bom uso dos recursos.","context":"L-I-M-P-E é um lembrete: Legalidade, Impessoalidade, Moralidade, Publicidade, Eficiência.","example":"Servidor que escolhe um amigo para receber vantagem viola impessoalidade e pode atingir outros princípios.","pitfall":"Um caso pode ferir vários princípios; a pergunta pede o MAIS direto.","reference":""},{"id":"u16","cat":"Direito","title":"Direitos individuais e remédios constitucionais","question":"Qual instrumento se relaciona com liberdade de locomoção?","options":["Habeas data","Habeas corpus","Ação popular","Ação civil pública"],"answer":1,"why":"O habeas corpus tutela a liberdade de locomoção.","principle":"Habeas corpus protege liberdade de locomoção contra ilegalidade ou abuso de poder; mandado de segurança protege direito líquido e certo, quando cabível; habeas data trata de acesso/retificação de dados pessoais nas hipóteses legais; ação popular permite a cidadão combater atos lesivos aos bens juridicamente protegidos.","context":"Remédio constitucional é ferramenta de proteção de direitos.","example":"Prisão ilegal → pense em habeas corpus. Negativa ilegal de certidão/documento com direito comprovável → examine mandado de segurança.","pitfall":"Não confunda “habeas corpus” (ir e vir) com “habeas data” (dados).","reference":""},{"id":"u17","cat":"Direito","title":"Direitos sociais e nacionalidade","question":"Qual é exemplo de direito social?","options":["Educação","Nome de rua","Cor de uniforme","Marca de telefone"],"answer":0,"why":"Educação integra o rol constitucional de direitos sociais.","principle":"O art. 6º apresenta direitos sociais. Nacionalidade distingue brasileiros natos e naturalizados conforme regras constitucionais. A banca pode apresentar situação e pedir a classificação ou um direito previsto.","context":"Direitos sociais cuidam de condições básicas; nacionalidade define vínculo jurídico com o Estado.","example":"Educação e saúde são exemplos de direitos sociais previstos constitucionalmente.","pitfall":"Nem todo direito constitucional é “direito social”; confira o capítulo aplicável.","reference":""},{"id":"u18","cat":"Direito","title":"Administração: cargo, emprego e função","question":"Estabilidade de servidor efetivo surge automaticamente no dia da posse?","options":["Sim","Não"],"answer":1,"why":"Em regra há três anos de efetivo exercício e avaliação especial de desempenho.","principle":"Servidores efetivos, concurso público, direitos e deveres, acumulações e estabilidade aparecem em Constituição e Estatuto paulista. A estabilidade constitucional, como regra, pressupõe cargo efetivo, concurso, período de três anos de efetivo exercício e avaliação especial de desempenho.","context":"Cargo público é um lugar definido em lei dentro de uma estrutura; emprego costuma seguir regime trabalhista.","example":"Passar em concurso e tomar posse não significa adquirir estabilidade no primeiro dia.","pitfall":"Não misture regime estatutário do TJ com contrato CLT de empresa privada.","reference":""},{"id":"u19","cat":"Direito","title":"Direito Penal: crime e processo não são sinônimos","question":"A descrição do comportamento que constitui crime é estudada em:","options":["Direito Penal","Português","Geometria","Direito Processual Civil"],"answer":0,"why":"O tipo penal define a conduta proibida.","principle":"Em Penal, decore menos nomes soltos e crie uma tabela: quem praticou? que conduta? houve intenção exigida? qual objeto protegido? Os artigos do edital focam falsidades e crimes contra a Administração/Justiça.","context":"Crime diz o que é proibido; processo diz como se investiga e julga.","example":"Um servidor que desvia dinheiro de que tem posse em razão do cargo pode cometer peculato, dependendo dos elementos do tipo.","pitfall":"As diferenças entre peculato, corrupção passiva e concussão dependem dos verbos do tipo penal.","reference":""},{"id":"u20","cat":"Direito","title":"Peculato: a confiança quebrada","question":"Qual sinal aponta para peculato-apropriação?","options":["Uso de abreviações","Apropriação de bem sob posse funcional","Falta de vírgula","Atraso de ônibus"],"answer":1,"why":"O núcleo é apropriar-se de bem com posse em razão do cargo.","principle":"No peculato-apropriação, o funcionário público se apropria de dinheiro, valor ou outro bem móvel de que tem posse em razão do cargo. Há outras modalidades; leia o art. 312 do CP. A relação com o cargo e a posse são pistas importantes.","context":"Imagine alguém encarregado de guardar o dinheiro da escola e que se apropria dele.","example":"Responsável pelo caixa da repartição toma para si valor sob sua guarda: pense em peculato.","pitfall":"A qualidade de funcionário e a descrição exata importam; não rotule qualquer furto como peculato.","reference":"Código Penal, art. 312"},{"id":"u21","cat":"Direito","title":"Corrupção passiva x concussão","question":"“Exigir vantagem indevida em razão da função” remete a:","options":["Concussão","Crase","Habeas data","Furto comum"],"answer":0,"why":"O verbo nuclear de concussão é “exigir”.","principle":"Corrupção passiva (art. 317): solicitar, receber ou aceitar promessa de vantagem indevida em razão da função. Concussão (art. 316): exigir vantagem indevida, valendo-se da função. A banca costuma trocar o verbo para testar a distinção.","context":"Duas palavras fazem diferença: SOLICITAR/RECEBER e EXIGIR.","example":"Servidor: “Pague para eu agilizar” pode sugerir solicitação; “Você tem que pagar ou sofrerá consequência” aponta para exigência.","pitfall":"A análise real depende dos fatos, mas o verbo da lei é atalho de prova.","reference":"Código Penal, arts. 316–317"},{"id":"u22","cat":"Direito","title":"Prevaricação: o interesse pessoal no atraso","question":"Qual detalhe é essencial no tipo de prevaricação?","options":["Interesse ou sentimento pessoal","Uso de Excel","Trabalho remoto","Quantidade de folhas"],"answer":0,"why":"A finalidade especial é componente do tipo descrito no art. 319.","principle":"Prevaricação (art. 319): retardar ou deixar de praticar indevidamente ato de ofício, ou praticá-lo contra disposição expressa de lei, para satisfazer interesse ou sentimento pessoal. O motivo pessoal específico é importante.","context":"É como alguém esconder uma tarefa pública por interesse particular.","example":"Servidor deixa processo parado de propósito para favorecer pessoa próxima: pode configurar prevaricação se os elementos estiverem presentes.","pitfall":"Atraso por excesso de trabalho, por si só, não prova prevaricação.","reference":"Código Penal, art. 319"},{"id":"u23","cat":"Direito","title":"Falsidade documental: verdade no papel","question":"Qual contraste é correto?","options":["Falsidade material e ideológica são sempre idênticas","Material envolve falsificação do documento; ideológica envolve declaração falsa no documento","Só documento particular importa","Não existem crimes de falsidade"],"answer":1,"why":"A diferença de natureza da falsidade ajuda a identificar os tipos.","principle":"O edital inclui crimes contra a fé pública (CP arts. 293–305 e correlatos). Diferencie falsificar documento (alterar/produzir material falso) de falsidade ideológica (inserir declaração falsa em documento verdadeiro, nos termos da lei).","context":"Documentos públicos dependem de confiança na autenticidade.","example":"Criar um documento público inteiramente falso é diferente de inserir informação falsa em um documento formalmente verdadeiro.","pitfall":"Falso conteúdo e falso suporte material não são expressões intercambiáveis.","reference":""},{"id":"u24","cat":"Direito","title":"Processo Civil: a viagem de uma ação","question":"A citação, em termos gerais, serve para:","options":["Chamar réu ou interessado a integrar a relação processual","Divulgar propaganda","Arquivar tudo automaticamente","Pagar salário"],"answer":0,"why":"Citação dá ciência e chama a integrar o processo.","principle":"Visão geral: petição inicial → análise judicial/citação → resposta do réu → prova/instrução quando cabível → decisão → eventuais recursos → cumprimento. O CPC traz muitas exceções e procedimentos específicos; use esta sequência como mapa inicial.","context":"Um processo é uma fila de etapas, não uma conversa sem regras.","example":"Uma pessoa cobra valor judicialmente; o réu é citado para integrar o processo e poder responder.","pitfall":"Não trate todos os procedimentos como idênticos; prazos e atos variam.","reference":"Código de Processo Civil, art. 238"},{"id":"u25","cat":"Direito","title":"Intimação x citação","question":"Avisar uma parte sobre decisão já proferida é, em geral:","options":["Citação","Intimação","Peculato","Denúncia"],"answer":1,"why":"O aviso de ato processual é intimação.","principle":"No CPC, citação convoca réu, executado ou interessado a integrar a relação processual. Intimação dá ciência a alguém sobre atos e termos do processo. Leia os dispositivos vigentes previstos no edital e as formas eletrônicas.","context":"Citação chama para a história; intimação informa sobre um ato dentro dela.","example":"Primeira convocação de réu: geralmente citação. Comunicação de decisão ao advogado: intimação.","pitfall":"O modo de comunicação pode variar; o conceito importa.","reference":"CPC, arts. 238 e 269"},{"id":"u26","cat":"Direito","title":"Prazos processuais: o relógio da Justiça","question":"No CPC, a contagem em dias dos prazos processuais considera, como regra:","options":["Dias corridos","Dias úteis","Apenas domingos","Apenas feriados"],"answer":1,"why":"O art. 219 do CPC dispõe sobre contagem em dias úteis.","principle":"No processo civil, como regra, prazos processuais em dias contam-se em dias úteis (art. 219 do CPC); existem hipóteses específicas e regras de início/suspensão. Processo penal tem disciplina diferente. Nunca transfira uma regra de um código para o outro.","context":"Um prazo é cronômetro com regras próprias.","example":"Um prazo de 5 dias úteis no CPC não significa simplesmente 5 dias corridos.","pitfall":"Feriados, suspensões, forma da intimação e espécie do prazo alteram a conta.","reference":"CPC, art. 219"},{"id":"u27","cat":"Direito","title":"Tutela de urgência: socorro antes do fim","question":"Dois requisitos típicos da tutela de urgência são:","options":["Probabilidade do direito e perigo de dano","Popularidade e sorte","Somente vontade do autor","Apenas valor alto da causa"],"answer":0,"why":"Os elementos centrais estão no art. 300 do CPC.","principle":"Uma tutela provisória pode proteger direito antes da decisão final. A tutela de urgência exige elementos que evidenciem probabilidade do direito e perigo de dano ou risco ao resultado útil do processo, com disciplina e limites legais.","context":"É como usar um guarda-chuva agora, antes de acabar a tempestade.","example":"Medida para evitar que a demora torne inútil uma decisão futura.","pitfall":"Probabilidade não significa certeza; decisão provisória não é sentença definitiva.","reference":"CPC, art. 300"},{"id":"u28","cat":"Direito","title":"Recursos: pedir reexame","question":"Em regra, contra sentença no CPC cabe:","options":["Apelação","Habeas corpus automaticamente","Mandado de prisão","Nenhum recurso"],"answer":0,"why":"A apelação é o recurso típico contra sentença.","principle":"O CPC lista recursos no art. 994, incluindo apelação e agravo de instrumento. Apelação, em regra, é interposta contra sentença (art. 1.009); agravo de instrumento cabe contra determinadas decisões interlocutórias previstas em lei.","context":"Recurso é tocar a campainha de uma instância ou órgão competente para pedir reavaliação.","example":"Sentença de primeiro grau: pense primeiro em apelação, depois confira exceções e regras específicas.","pitfall":"Nem toda decisão admite qualquer recurso; cabimento importa.","reference":"CPC, arts. 994 e 1.009"},{"id":"u29","cat":"Direito","title":"Juizados Especiais Cíveis","question":"Qual princípio caracteriza os Juizados?","options":["Formalismo máximo","Celeridade e simplicidade","Sigilo absoluto","Julgamento sem contraditório"],"answer":1,"why":"A lei valoriza simplicidade, informalidade e rapidez.","principle":"A Lei 9.099/1995 busca conciliação, simplicidade, oralidade, informalidade, economia processual e celeridade. O edital cita arts. 3º a 19. A competência e a necessidade de advogado variam conforme situação e limites legais.","context":"É uma via de justiça pensada para conflitos menos complexos.","example":"Conflito de consumo simples pode tramitar no Juizado, desde que preencha os requisitos legais.","pitfall":"Juizado não é um lugar “sem regras”; há limites de valor, matéria e partes.","reference":"Lei 9.099/1995, art. 2º (princípios como contexto)"},{"id":"u30","cat":"Direito","title":"Processo Penal: quem faz o quê?","question":"Quem julga a causa penal?","options":["Juiz competente","Somente escrivão","Testemunha","Réu"],"answer":0,"why":"A função jurisdicional pertence ao juiz competente.","principle":"No processo penal, estude juiz, Ministério Público, acusado e defensor, impedimentos/suspeições, citação e intimação, procedimentos e recursos, dentro dos artigos indicados. O direito de defesa e o devido processo são fundamentais.","context":"É um time com papéis distintos: juiz decide, acusação acusa, defesa se defende.","example":"O magistrado não deve agir como defensor da acusação; cada agente tem função própria.","pitfall":"Evite misturar a função do Ministério Público com a do magistrado.","reference":""},{"id":"u31","cat":"Direito","title":"JECRIM e infrações de menor potencial ofensivo","question":"Transação penal e suspensão condicional do processo são:","options":["Exatamente iguais","Institutos distintos, com requisitos próprios","Tipos de planilha","Recursos civis"],"answer":1,"why":"Cada instrumento tem disciplina legal própria.","principle":"No âmbito da Lei 9.099/1995, há institutos como composição dos danos civis, transação penal e suspensão condicional do processo, conforme requisitos legais. Esses institutos não são sinônimos.","context":"O Juizado Especial Criminal possui ferramentas próprias para conflitos penais menos graves.","example":"Uma infração de menor potencial ofensivo pode seguir procedimento com tentativa de solução consensual quando preenchidos os requisitos.","pitfall":"Não suponha que o benefício seja automático ou disponível a qualquer crime.","reference":"Lei 9.099/1995, arts. 60–89 previstos no edital"},{"id":"u32","cat":"Direito","title":"Citação penal e defesa","question":"Uma finalidade essencial da citação do acusado é:","options":["Permitir exercício de defesa","Cancelar a denúncia por si só","Escolher o juiz","Emitir CPF"],"answer":0,"why":"A ciência formal permite contraditório e ampla defesa.","principle":"O CPP disciplina formas de citação e intimação e procedimentos. A citação em processo penal chama o acusado; situações especiais exigem atenção ao procedimento legal. O edital cobra trechos específicos dos arts. 351 em diante.","context":"Ninguém deve ser julgado sem a oportunidade de saber da acusação e se defender.","example":"A defesa precisa ter oportunidade de conhecer os fatos imputados e participar do processo conforme a lei.","pitfall":"Não copie mecanicamente regras de prazo do CPC para o CPP.","reference":""},{"id":"u33","cat":"Direito","title":"Estatuto do servidor de SP","question":"Para estudar o estatuto, qual estratégia é mais segura?","options":["Decorar boatos","Comparar deveres, proibições e sanções na lei","Ignorar prazos","Usar apenas vídeos antigos"],"answer":1,"why":"A redação legal e as distinções entre categorias são decisivas.","principle":"A Lei estadual 10.261/1968 regula temas como provimento, exercício, deveres, proibições e penalidades nos artigos especificados. Leia a letra da lei, monte tabela “dever x proibição x consequência”, e verifique o texto vigente.","context":"Imagine o manual de convivência e deveres de quem trabalha no estado.","example":"Guardar sigilo de informações protegidas e tratar o público adequadamente são exemplos de cuidados funcionais.","pitfall":"Resumo não substitui o artigo exato quando a banca pergunta literalidade.","reference":"Lei estadual 10.261/1968, artigos do Anexo VIII"},{"id":"u34","cat":"Direito","title":"Improbidade não é qualquer erro","question":"Qual afirmação é mais adequada à lei atual?","options":["Todo erro é improbidade","A tipificação exige análise dos requisitos legais, incluindo dolo","Só existe improbidade se houver prisão","Nunca há sanção"],"answer":1,"why":"Improbidade depende de requisitos próprios da Lei 8.429/1992.","principle":"A Lei 8.429/1992 disciplina atos de improbidade, alterada especialmente pela Lei 14.230/2021. A caracterização dos tipos exige dolo conforme a legislação vigente; avalie enriquecimento ilícito, prejuízo ao erário e violação a princípios, entre os requisitos legais.","context":"Erro administrativo e improbidade não são automaticamente a mesma coisa.","example":"Um erro acidental de preenchimento não vira automaticamente improbidade.","pitfall":"Desorganização ou culpa, por si, não equivale ao dolo previsto na lei.","reference":"Lei 8.429/1992, redação vigente"},{"id":"u35","cat":"Direito","title":"Legislação interna: regras da casa","question":"Qual norma do edital aborda teletrabalho no TJSP?","options":["Resolução 850/2021","Art. 312 do Código Penal","Lei 9.099/1995","Regra de três"],"answer":0,"why":"A Resolução TJSP 850/2021 regula teletrabalho.","principle":"O edital de 2026 inclui Resolução TJSP 850/2021 (teletrabalho), 963/2025 (governança e utilização do eproc), LC 1.111/2010 (carreira), Regimento Interno e trechos das Normas da Corregedoria. Aqui a banca pode cobrar disposições literais.","context":"O TJ possui também regras para organizar seus sistemas e servidores.","example":"Eproc é um sistema ligado à tramitação eletrônica; a resolução específica trata de sua governança e uso no TJSP.","pitfall":"Não adivinhe detalhes como competência exata de órgão: consulte a resolução oficial indicada no edital.","reference":"Edital 02/2026, Anexo VIII, seção 6"},{"id":"u36","cat":"Direito","title":"Normas da Corregedoria e eproc","question":"Se a questão exigir a atribuição específica de um setor, você deve:","options":["Adivinhar pelo nome","Consultar a disposição interna prevista no edital","Ignorar a norma","Responder sempre “juiz”"],"answer":1,"why":"A competência administrativa específica está na legislação interna.","principle":"As Normas da Corregedoria padronizam rotinas, documentação, fluxo e organização do serviço judicial. Já a Resolução 963/2025 trata de governança e uso do eproc. Estude os capítulos e seções delimitados, sempre no texto oficial.","context":"Pense em um manual de organização da secretaria judicial.","example":"Questões podem perguntar quem registra determinada movimentação ou qual providência é prevista pela norma.","pitfall":"Fluxo interno detalhado não pode ser deduzido apenas da experiência no computador: precisa da norma.","reference":"Normas da Corregedoria TJSP; Res. 963/2025"},{"id":"u37","cat":"Lógica","title":"Proposição: frase que pode ser verdadeira ou falsa","question":"Qual é proposição?","options":["Que horas são?","Estude agora!","2 + 2 = 4","Nossa!"],"answer":2,"why":"A igualdade é declaração avaliável como verdadeira.","principle":"“São Paulo fica no Brasil” é proposição. “Feche a porta!” é ordem e não recebe valor de verdade no mesmo sentido. Em lógica de concurso, identifique frases declarativas com valor de verdade.","context":"Proposição é uma lâmpada: ou ligada (V), ou desligada (F).","example":"“5 é par” é proposição falsa; ainda é uma proposição.","pitfall":"Proposição não precisa ser verdadeira; precisa ser avaliável como V ou F.","reference":""},{"id":"u38","cat":"Lógica","title":"Se P, então Q","question":"Se houve distribuição, houve número. Não houve número. Então:","options":["Houve distribuição","Não houve distribuição","Houve dois números","Nada pode ser dito"],"answer":1,"why":"É a contrapositiva válida: não Q → não P.","principle":"Na condicional “Se P, então Q”, a única situação que torna a frase falsa é P verdadeiro com Q falso. A contrapositiva “Se não Q, então não P” é equivalente à original. Não inverta sem cuidado.","context":"É um dominó: quando P ocorre, Q deve ocorrer.","example":"Se chove, rua molha. Rua não molhou → não choveu (dentro da premissa idealizada). Rua molhou NÃO prova que choveu.","pitfall":"Confundir “se P então Q” com “se Q então P” é pegadinha clássica.","reference":""},{"id":"u39","cat":"Lógica","title":"E, OU, NÃO","question":"A frase “P e Q” é verdadeira quando:","options":["Só P","Só Q","Ambas P e Q","Nenhuma"],"answer":2,"why":"A conjunção exige as duas proposições verdadeiras.","principle":"“P E Q” só é verdadeiro se ambos forem verdadeiros. “P OU Q” (ou inclusivo) é verdadeiro se pelo menos um for verdadeiro. “NÃO P” inverte. A Vunesp pode pedir tabela-verdade ou negações.","context":"Conectivos funcionam como botões combinados.","example":"“Ana trabalha E estuda”: basta uma parte falsa para a conjunção ser falsa.","pitfall":"No “ou” lógico inclusivo, ambas podem ser verdadeiras.","reference":""},{"id":"u40","cat":"Lógica","title":"Negar “todos” e “alguns”","question":"Negação de “Todos os processos terminaram”:","options":["Nenhum terminou","Pelo menos um não terminou","Todos começaram","Alguns foram arquivados"],"answer":1,"why":"Um único contraexemplo basta para negar a universal.","principle":"Negação de “todos são A” = “algum não é A”; negação de “algum é A” = “nenhum é A”. “Nenhum” = “todos não”. Use desenhos de conjuntos para visualizar.","context":"Para negar “todos têm”, basta encontrar UM que não tenha.","example":"“Todos passaram” é negada por “Pelo menos uma pessoa não passou”, e NÃO por “Ninguém passou”.","pitfall":"Negação não é exagerar para o extremo oposto.","reference":""},{"id":"u41","cat":"Lógica","title":"Diagramas e conjuntos","question":"Todos os gatos são mamíferos. Mimi é gato. Logo:","options":["Mimi é mamífero","Todo mamífero é gato","Mimi é ave","Nenhuma conclusão"],"answer":0,"why":"Aplicação direta da relação de inclusão.","principle":"“Todo A é B” coloca A inteiramente dentro de B. “Algum A é B” informa interseção. “Nenhum A é B” informa círculos disjuntos. Conclusões precisam valer em todos os desenhos compatíveis.","context":"Imagine círculos de brinquedos: um círculo para cães e outro para animais.","example":"Todos os escreventes são servidores; Joana é escrevente → Joana é servidora.","pitfall":"Não conclua que todo servidor é escrevente.","reference":""},{"id":"u42","cat":"Lógica","title":"Sequências: encontre a regra","question":"Qual vem depois de 3, 6, 12, 24?","options":["27","36","48","72"],"answer":2,"why":"Cada termo é o dobro do anterior.","principle":"Teste diferenças, multiplicações, alternância e agrupamentos. Em sequências de letras, cheque posições no alfabeto. Em figuras, observe rotação, número de formas ou preenchimento.","context":"Olhe os degraus entre números antes de adivinhar o próximo.","example":"2, 5, 8, 11… soma sempre 3. Próximo: 14.","pitfall":"Não aceite a primeira regra que parece funcionar com só dois termos.","reference":""},{"id":"u43","cat":"Lógica","title":"Problemas de relações","question":"Com apenas Ana e Bruno, um em cada turno, Bruno está de manhã. Ana está:","options":["De manhã","À tarde","Nos dois","Impossível dizer"],"answer":1,"why":"Com dois turnos exclusivos, o outro sobra para Ana.","principle":"Monte tabela com linhas (pessoas) e colunas (objetos/horários), marque ✓ e ×. Leia “apenas”, “exatamente”, “antes”, “depois”. Volte para checar se usou todas as pistas.","context":"É detetive com pistas: anote os personagens e elimine impossibilidades.","example":"Ana não é do turno da manhã; Bruno é da manhã. Então Ana precisa de outro turno, no problema de turnos exclusivos.","pitfall":"Não conclua o horário de Ana sem saber quais possibilidades restam.","reference":""},{"id":"u44","cat":"Matemática","title":"Porcentagem: pedaços de 100","question":"25% de 240 é:","options":["40","50","60","80"],"answer":2,"why":"Um quarto de 240 = 60.","principle":"10% = 0,10; 25% = 1/4; 50% = metade. Para encontrar 15% de 200, multiplique 200 × 0,15 = 30. Para desconto, subtraia; para aumento, some.","context":"Por cento significa “de cada cem”.","example":"Desconto de 20% sobre R$ 150: 150 × 0,20 = 30; preço final R$ 120.","pitfall":"Não some percentuais sucessivos sem verificar a base.","reference":""},{"id":"u45","cat":"Matemática","title":"Porcentagem sucessiva","question":"Depois de reduzir 100 em 10%, sobra:","options":["90","100","110","80"],"answer":0,"why":"100 − 10 = 90.","principle":"Comece com 100. Desconto de 20% → 80. Aumento de 20% sobre 80 → 96. Portanto, uma queda de 20% e uma alta de 20% não se anulam.","context":"Quando um preço muda, a próxima porcentagem usa o preço NOVO.","example":"240 processos: resolve 25% → restam 180; resolve 20% de 180 → restam 144.","pitfall":"20% de 180 é 36, não 48.","reference":""},{"id":"u46","cat":"Matemática","title":"Regra de três: quanto mais, quanto mais?","question":"12 processos em 3 horas, mesmo ritmo. Em 5 horas:","options":["15","18","20","24"],"answer":2,"why":"4 processos por hora × 5 = 20.","principle":"Grandezas diretamente proporcionais: uma cresce e a outra cresce na mesma razão. Inversamente proporcionais: uma cresce e a outra diminui. Identifique antes de multiplicar cruzado.","context":"Uma receita para 2 pessoas pode ser dobrada para 4.","example":"12 processos em 3 horas → 4 por hora → em 5 horas, 20 processos.","pitfall":"Se mais trabalhadores fazem o mesmo serviço mais rápido, a proporção não é direta.","reference":""},{"id":"u47","cat":"Matemática","title":"Média simples e ponderada","question":"Média simples de 4, 6 e 8 é:","options":["5","6","7","8"],"answer":1,"why":"(4+6+8)/3 = 18/3 = 6.","principle":"Média simples = soma ÷ quantidade. Média ponderada = soma dos produtos valor × peso ÷ soma dos pesos. Leia o enunciado: notas com pesos diferentes pedem ponderada.","context":"Média é dividir igualmente uma pilha de pontos.","example":"Notas 6 (peso 1) e 8 (peso 2): (6×1 + 8×2)/3 = 22/3 ≈ 7,33.","pitfall":"Média de 6 e 8 com pesos diferentes NÃO é necessariamente 7.","reference":""},{"id":"u48","cat":"Matemática","title":"Equação: a balança","question":"Se 2x+6=16, x vale:","options":["3","4","5","6"],"answer":2,"why":"2x=10; x=5.","principle":"Resolver 3x + 5 = 20: subtraia 5 em ambos os lados → 3x=15; divida por 3 → x=5. Equações de segundo grau podem exigir fatoração ou fórmula. Sistemas pedem encontrar valores que satisfazem todas as equações.","context":"Se tirou algo de um lado, tire do outro também.","example":"2x − 4 = 10 → 2x=14 → x=7.","pitfall":"Ao “passar para o outro lado”, explique a operação correspondente.","reference":""},{"id":"u49","cat":"Matemática","title":"MMC e MDC: encontros e divisões","question":"MMC(4,6) é:","options":["2","6","12","24"],"answer":2,"why":"Múltiplos de 4: 4,8,12; de 6: 6,12. Primeiro encontro: 12.","principle":"MMC: menor múltiplo comum positivo. MDC: maior divisor comum. Exemplo: alarmes a cada 4 e 6 minutos coincidem novamente após 12 minutos. Dividir 24 e 36 em grupos iguais máximos leva ao MDC 12.","context":"MMC ajuda a encontrar quando eventos voltam a coincidir; MDC divide em grupos iguais sem sobrar.","example":"Ônibus a cada 10 e 15 min: coincidência após 30 min.","pitfall":"MMC não é o mesmo que MDC.","reference":""},{"id":"u50","cat":"Matemática","title":"Juros simples","question":"Juros simples de R$ 200 a 5% ao mês por 2 meses:","options":["R$ 10","R$ 20","R$ 25","R$ 40"],"answer":1,"why":"200×0,05×2=20.","principle":"J = C × i × t. C capital, i taxa decimal por período, t número de períodos na mesma unidade. Montante M = C + J. Se capital é 1.000, taxa 2% ao mês por 3 meses: J=1000×0,02×3=60.","context":"Em juros simples, o acréscimo por período tem base fixa.","example":"R$ 500 a 1% ao mês por 4 meses → juros R$ 20.","pitfall":"Não misture taxa mensal com tempo em anos sem converter.","reference":""},{"id":"u51","cat":"Matemática","title":"Geometria e tabelas","question":"Área de retângulo 5 m × 2 m:","options":["7 m²","10 m²","14 m²","25 m²"],"answer":1,"why":"5×2=10 m².","principle":"Perímetro: contorno. Área: superfície. Volume: espaço ocupado. Retângulo: área = base×altura. Triângulo: área = base×altura/2. Pitágoras em triângulo retângulo: a²+b²=c². Leia unidades.","context":"Geometria mede chão, borda, caixa e distância.","example":"Sala 4 m × 3 m: área 12 m², perímetro 14 m.","pitfall":"m² não é igual a m; unidades fazem parte da resposta.","reference":""},{"id":"u52","cat":"Informática","title":"Windows: arquivos e pastas","question":"Um arquivo .xlsx costuma ser:","options":["Planilha","Imagem PNG","Vídeo","Áudio"],"answer":0,"why":"A extensão xlsx é usada por planilhas do Excel.","principle":"Conheça copiar, mover, renomear, excluir, extensão, atalhos e área de transferência. Um atalho aponta para algo; não é necessariamente o próprio arquivo. Explorar arquivos no Windows exige atenção ao caminho e à extensão.","context":"Pastas são gavetas; arquivos são as folhas guardadas nelas.","example":"Relatório.docx é documento; Relatório.xlsx é planilha; um atalho pode apontar para qualquer um deles.","pitfall":"Excluir um atalho normalmente não exclui o arquivo original.","reference":""},{"id":"u53","cat":"Informática","title":"Word: revisão de texto","question":"Qual ferramenta registra edições para revisão?","options":["Controlar Alterações","Calculadora","Paint","Gerenciador de Tarefas"],"answer":0,"why":"É o recurso apropriado para rastrear mudanças.","principle":"No Word, veja estilos, formatação, tabelas, cabeçalho, numeração, quebras, sumário e Controlar Alterações. Comentários registram observações; comparar documentos ajuda a identificar diferenças entre versões.","context":"Controlar alterações é como colocar etiquetas em cada mudança feita num livro.","example":"Editor muda uma frase e o autor pode aceitar ou rejeitar a alteração.","pitfall":"Comentário e alteração rastreada não são a mesma coisa.","reference":""},{"id":"u54","cat":"Informática","title":"Excel: fórmula é receita","question":"Ao copiar =$A2*B$1 de C2 para D3, vira:","options":["=$A3*C$1","=$B3*C$2","=$A2*B$1","=A3*$C1"],"answer":0,"why":"A fica fixa, linha 2 vira 3; B vira C, linha 1 fica fixa.","principle":"Toda fórmula começa com “=”. “=SOMA(A1:A3)” soma intervalo. A referência A1 aponta coluna A e linha 1. Ao copiar fórmula, referências relativas podem mudar. O $ fixa coluna ou linha conforme posição.","context":"Planilha é tabela que calcula sozinha usando receitas.","example":"Em C2: =$A2*B$1. Copiando uma coluna à direita e uma linha abaixo → =$A3*C$1.","pitfall":"“$A2” fixa apenas a coluna; “B$1” fixa apenas a linha.","reference":""},{"id":"u55","cat":"Informática","title":"Excel: SE e filtros","question":"Qual ferramenta destaca automaticamente prazos vencidos?","options":["Formatação condicional","Zoom","Quebra de página","Localizar fonte"],"answer":0,"why":"Ela aplica formatos por condições.","principle":"Exemplo: =SE(A2>=7;\"Aprovado\";\"Revisar\") em planilha pt-BR. Filtros ocultam temporariamente linhas fora do critério, sem apagá-las. Formatação condicional colore células de acordo com regras.","context":"SE é um porteiro: se uma condição é cumprida, faz A; se não, faz B.","example":"Planilha de prazos: data vencida e ainda não paga → destaque visual.","pitfall":"Filtrar não apaga dados; cuidado ao classificar uma só coluna sem acompanhar as outras.","reference":""},{"id":"u56","cat":"Informática","title":"Internet, URL e phishing","question":"Qual atitude é mais segura?","options":["Clicar em link urgente do desconhecido","Conferir endereço oficial e remetente","Compartilhar senha","Desativar verificações"],"answer":1,"why":"Verificar origem e domínio ajuda a evitar phishing.","principle":"Entenda domínio, endereço web, link, navegador e HTTPS. HTTPS protege a conexão, mas não garante que um site seja legítimo. Cuidado com mensagens que pedem senha ou urgência e links parecidos com sites oficiais.","context":"URL é endereço de uma casa online; phishing é uma carta falsa querendo roubar chave.","example":"“tribunal-seguro-exemplo.com” não vira oficial só porque tem “tribunal” no nome.","pitfall":"Cadeado HTTPS não prova a identidade confiável de uma empresa.","reference":""},{"id":"u57","cat":"Informática","title":"E-mail: CC, CCO e anexos","question":"Qual campo oculta destinatários dos demais?","options":["Assunto","CCO","CC","Para"],"answer":1,"why":"CCO é cópia oculta.","principle":"Para = destinatários principais; CC = cópia visível; CCO = cópia oculta. Conheça anexar, responder, responder a todos, encaminhar, spam e links. Atenção à proteção de dados em comunicação institucional.","context":"CCO é como mandar cópias sem mostrar os outros endereços.","example":"Aviso para destinatários externos sem expor a lista: avalie CCO.","pitfall":"Responder a todos envia também a quem não precisava receber.","reference":""},{"id":"u58","cat":"Informática","title":"Teams, OneDrive e colaboração","question":"Para permitir leitura sem edição, use permissão:","options":["Editar","Visualizar","Excluir","Administrador"],"answer":1,"why":"Visualização limita alterações.","principle":"No Microsoft 365, Teams oferece conversas e reuniões; OneDrive guarda e compartilha arquivos, com permissões. Word/Excel podem permitir colaboração em documentos, conforme a configuração. Saiba diferenciar editar e visualizar.","context":"OneDrive é armário de arquivos na nuvem; Teams é sala virtual de trabalho.","example":"Se você só quer que colega leia, compartilhe com permissão de visualização.","pitfall":"Link público com permissão de edição pode expor documentos ou permitir alteração indevida.","reference":""},{"id":"u59","cat":"Gerais","title":"Atualidades: como estudar fatos sem decorar manchetes","question":"Qual é melhor forma de revisar atualidades?","options":["Memorizar só título","Organizar fato, data, atores, contexto e impacto","Ignorar data","Confiar em corrente"],"answer":1,"why":"A prova costuma cobrar compreensão e contextualização.","principle":"O edital abrange fatos políticos, econômicos, sociais e culturais nacionais e internacionais a partir do primeiro semestre de 2026. Para cada tema, responda: o que aconteceu? quando? quais atores? por que importa? qual consequência? Consulte fontes confiáveis e atualizadas.","context":"Notícia é uma peça de quebra-cabeça: contexto é a imagem da caixa.","example":"Tema político: identifique instituição, decisão, repercussão e diferença entre notícia e opinião.","pitfall":"Não use exemplos antigos como se fossem fatos de 2026; esse módulo ensina método, não apresenta boletim atualizado.","reference":""},{"id":"u60","cat":"Gerais","title":"Estatuto da Pessoa com Deficiência","question":"A inclusão busca principalmente:","options":["Igualdade de oportunidades e eliminação de barreiras","Separar todas as pessoas","Evitar adaptações","Negar autonomia"],"answer":0,"why":"A lei busca inclusão e participação em igualdade.","principle":"A Lei 13.146/2015 trata de direitos, acessibilidade, inclusão e igualdade de oportunidades. O edital delimita arts. 1º–13 e 34–38. Estude conceitos de deficiência, barreiras, discriminação, autonomia e direitos no trabalho.","context":"Acessibilidade é remover barreiras para que pessoas participem em igualdade.","example":"Um sistema público que oferece recursos acessíveis reduz barreiras à participação.","pitfall":"Não trate pessoa com deficiência como incapaz por definição.","reference":"Lei 13.146/2015, arts. 1º–13 e 34–38"},{"id":"u61","cat":"Redação","title":"Redação: a arquitetura do texto","question":"Uma tese serve para:","options":["Apresentar posição defendida","Substituir todos os argumentos","Copiar o título","Contar uma história sem conexão"],"answer":0,"why":"É a ideia central sustentada ao longo do texto.","principle":"A redação pede texto dissertativo-argumentativo. Estrutura funcional: introdução com tema e tese; desenvolvimento 1 com argumento; desenvolvimento 2 com outro argumento; conclusão que amarra o raciocínio. Leia sempre a proposta da prova.","context":"Escrever uma dissertação é construir casa: entrada, cômodos, saída.","example":"Tema hipotético: “tecnologia e acesso à Justiça”. Tese: soluções digitais ampliam acesso, mas precisam ser acompanhadas de inclusão digital.","pitfall":"Não comece decorando frases prontas que não respondem ao tema; não é obrigatória proposta de intervenção.","reference":"Edital 02/2026, capítulo XI"},{"id":"u62","cat":"Redação","title":"Como transformar opinião em argumento","question":"O que fortalece um argumento?","options":["Dado inventado","Relação lógica entre causa, exemplo e tese","Frase sem sentido","Repetir a mesma ideia"],"answer":1,"why":"A coerência entre explicação e tese constrói força argumentativa.","principle":"Use um caminho: afirmação → explicação → exemplo plausível → ligação com a tese. Faça parágrafos claros, sem exagero retórico, respeitando o tema. Citações são opcionais: argumento bem explicado vale mais que frase famosa sem contexto.","context":"Opinião é “acho”; argumento é “acho por causa de X, que produz Y”.","example":"“A acessibilidade digital é essencial” → porque serviços eletrônicos sem recursos inclusivos podem excluir usuários → isso compromete acesso igualitário.","pitfall":"Não invente dados estatísticos para parecer convincente.","reference":""},{"id":"u63","cat":"Redação","title":"Revisão final: 5 perguntas","question":"A redação exige necessariamente proposta de intervenção ao estilo ENEM?","options":["Sim","Não"],"answer":1,"why":"O edital afirma que não é necessária uma conclusão com proposta de intervenção.","principle":"Confira: (1) respondi ao tema? (2) tenho tese clara? (3) cada parágrafo acrescenta algo? (4) concordância, pontuação e ortografia estão adequadas? (5) dá para ler facilmente? O edital informa que textos muito curtos têm restrições na pontuação e que não é necessária proposta de intervenção.","context":"Revise a redação como revisor de um jornal.","example":"Antes de entregar, releia cada frase procurando sujeito, verbo e conectivo.","pitfall":"Não deixe toda a revisão para os últimos dez segundos.","reference":"Edital 02/2026, capítulo XI"},{"id":"u67","cat":"Português","title":"Fato, opinião e inferência","question":"Qual conclusão é segura sobre “Alguns usuários preferem atendimento online”?","options":["Ninguém prefere atendimento físico","Todos preferem online","Uma parte dos usuários prefere online","O atendimento físico foi extinto"],"answer":2,"why":"“Alguns” não significa “todos”.","principle":"Fato é algo verificável; opinião avalia ou julga; inferência decorre de pistas. A Vunesp pode apresentar uma alternativa plausível, mas que extrapola o texto. Procure o trecho que sustenta sua escolha.","context":"Uma informação escrita é como uma peça de quebra-cabeça; a conclusão precisa encaixar nas peças disponíveis.","example":"Texto: “O tribunal ampliou os canais digitais.” Fato: houve ampliação. Não se pode concluir que o atendimento presencial acabou.","pitfall":"Evite trocar “alguns” por “todos” ou uma possibilidade por certeza.","reference":""},{"id":"u68","cat":"Português","title":"Ambiguidade e reescrita","question":"Qual reescrita elimina a ambiguidade?","options":["O chefe avisou o servidor de que ele seria promovido.","O chefe avisou o servidor sobre sua promoção.","O chefe avisou: “Você, servidor, será promovido.”","O chefe avisou-o de que ele seria promovido."],"answer":2,"why":"A fala direta identifica quem será promovido.","principle":"Ambiguidade pode nascer do posicionamento de adjuntos, pronomes e pontuação. Em reescritas, confira se o sentido, os sujeitos e as relações lógicas foram mantidos.","context":"Duas interpretações possíveis são como uma placa que aponta para dois caminhos.","example":"“O chefe avisou o servidor de que ele seria promovido.” Quem seria promovido? O pronome pode criar dúvida.","pitfall":"Trocar uma palavra por sinônimo não garante sentido equivalente no contexto.","reference":""},{"id":"u69","cat":"Português","title":"Orações subordinadas: causa, condição e concessão","question":"Em “Caso o documento chegue, analisaremos”, “caso” expressa:","options":["Comparação","Concessão","Causa","Condição"],"answer":3,"why":"A análise fica condicionada ao recebimento.","principle":"Causais: porque, já que. Condicionais: se, caso. Concessivas: embora, mesmo que. Temporais: quando, assim que. A relação não depende só da palavra isolada; leia as duas orações.","context":"Uma oração explica por que, quando ou apesar de quê outra acontece.","example":"“Se houver vaga, serei chamado” apresenta condição, não uma garantia de chamada.","pitfall":"“Embora” indica concessão; “portanto” indica conclusão.","reference":""},{"id":"u70","cat":"Português","title":"Voz ativa e voz passiva","question":"Qual é a passiva de “A equipe conferiu o documento”?","options":["Conferiu-se a equipe do documento.","A equipe foi conferida pelo documento.","O documento conferiu a equipe.","O documento foi conferido pela equipe."],"answer":3,"why":"O objeto “documento” vira sujeito paciente.","principle":"Ativa: “O cartório publicou a decisão.” Passiva: “A decisão foi publicada pelo cartório.” O tempo verbal e a relação agente/paciente devem ser preservados na transformação.","context":"Na ativa, alguém pratica a ação; na passiva, o foco vai para o alvo da ação.","example":"“Os servidores revisaram os autos” → “Os autos foram revisados pelos servidores”.","pitfall":"Nem toda oração com “se” está na voz passiva; identifique a estrutura.","reference":""},{"id":"u71","cat":"Português","title":"Concordância nominal e paralelismo","question":"Qual expressão está correta?","options":["As cópias seguem anexas.","As cópia seguem anexa.","As cópias segue anexas.","As cópias seguem anexo."],"answer":0,"why":"“Anexas” concorda com “cópias”.","principle":"Adjetivos e artigos concordam em gênero e número, observadas construções especiais. Em listas, paralelismo mantém estruturas equivalentes: “analisar processos, redigir documentos e atender usuários”.","context":"As palavras que acompanham o nome precisam combinar com ele.","example":"“As certidões anexas” (adjetivo plural); “documentos em anexo” (locução).","pitfall":"A banca gosta de expressões “é necessário”, “anexo”, “meio” e “bastante”.","reference":""},{"id":"u72","cat":"Português","title":"Pronomes relativos","question":"Qual construção está adequada?","options":["O livro cujo autor foi premiado.","O livro cujo o autor foi premiado.","O livro aonde li.","A lei onde discordo."],"answer":0,"why":"“Cujo” indica posse sem artigo após ele.","principle":"“O documento que chegou” retoma “documento”. “Cujo” indica posse e não recebe artigo depois: “autor cujo livro...”. “Onde” remete a lugar; “aonde”, com movimento e verbo que pede “a”.","context":"O relativo evita repetição e liga duas informações sobre o mesmo nome.","example":"“A cidade onde trabalho”; “A cidade aonde irei”.","pitfall":"Não use “onde” para retomar qualquer ideia abstrata.","reference":""},{"id":"u73","cat":"Português","title":"Regência verbal: assistir, visar e aspirar","question":"No sentido de presenciar, qual está correta?","options":["Assistiu a audiência (uso formal cobrado).","Assistiu pela audiência.","Assistiu na audiência.","Assistiu à audiência."],"answer":3,"why":"A construção normativa é assistir a + a audiência = à audiência.","principle":"Assistir no sentido de ver pede “a” na norma-padrão. Visar no sentido de almejar geralmente pede “a”; visar no sentido de pôr visto é transitivo direto. Aspirar no sentido de desejar pede “a”; de inalar é direto.","context":"Um mesmo verbo pode mudar de preposição conforme o sentido.","example":"“Assistimos ao julgamento”; “aspira ao cargo”; “aspirou o ar”.","pitfall":"Não decore o verbo sem lembrar qual significado foi usado.","reference":""},{"id":"u74","cat":"Português","title":"Colocação pronominal","question":"Qual segue a norma-padrão?","options":["Me informaram ontem, em redação formal estrita.","Nunca me informaram sobre a mudança.","Não informaram-me nunca.","Nunca informaram-me sobre a mudança."],"answer":1,"why":"O termo negativo “nunca” atrai o pronome.","principle":"Próclise: antes (“não me avisaram”). Ênclise: depois (“avisaram-me”). Mesóclise: no meio de futuro, em contextos formais (“avisar-me-ão”). Palavras negativas, relativos e certos advérbios atraem a próclise.","context":"A posição do pronome muda segundo fatores de atração e início de frase.","example":"“Jamais se esqueceram do prazo”: “jamais” atrai “se”.","pitfall":"Não comece oração formal com pronome oblíquo átono quando a norma-padrão exigir ênclise.","reference":""},{"id":"u75","cat":"Português","title":"Pontuação do aposto e vocativo","question":"Em “Ana, revise o relatório”, “Ana” é:","options":["Vocativo","Objeto direto","Adjunto adverbial","Sujeito da oração"],"answer":0,"why":"É a pessoa chamada pelo falante.","principle":"Aposto explicativo acrescenta informação; vocativo chama uma pessoa. Não separe o sujeito do verbo só porque ele é longo. Ponto e vírgula pode separar partes de enumerações extensas.","context":"Quem explica e quem é chamado podem ficar entre vírgulas.","example":"“Carlos, escrevente do fórum, chegou.” (aposto) e “Carlos, venha aqui.” (vocativo).","pitfall":"O aposto restritivo nem sempre recebe vírgulas.","reference":""},{"id":"u76","cat":"Português","title":"Semântica: pressuposto e subentendido","question":"“Ele deixou de faltar” pressupõe que:","options":["Antes faltava.","Nunca faltou.","Agora sempre falta.","Foi dispensado."],"answer":0,"why":"“Deixar de” pressupõe a ocorrência anterior.","principle":"“O servidor voltou a estudar” pressupõe que ele já estudava antes. Pressupostos costumam ser ativados por “voltar a”, “deixar de”, “ainda”. Subentendido depende mais do contexto e pode não ser obrigatório.","context":"Às vezes o texto informa algo sem declarar diretamente.","example":"“Ela parou de reclamar” pressupõe que reclamava.","pitfall":"Não trate qualquer hipótese sugerida como informação comprovada.","reference":""},{"id":"u77","cat":"Direito","title":"CF: legalidade, liberdade e igualdade","question":"Qual regra expressa a legalidade do art. 5º?","options":["Só há direitos para servidores.","Ninguém é obrigado a agir senão em virtude de lei.","O administrador pode criar qualquer dever.","Todo direito é absoluto."],"answer":1,"why":"A legalidade limita imposições ao cidadão.","principle":"Art. 5º: ninguém será obrigado a fazer ou deixar de fazer algo senão em virtude de lei. A igualdade perante a lei convive com tratamentos diferenciados justificáveis para efetivar direitos. Estude também inviolabilidade da intimidade e devido processo legal.","context":"A Constituição é uma regra de proteção tanto para o cidadão quanto para o Estado.","example":"O Estado não pode inventar obrigação sem fundamento legal.","pitfall":"Direito fundamental não significa autorização para prejudicar terceiros.","reference":"CF/1988, art. 5º"},{"id":"u78","cat":"Direito","title":"CF: habeas corpus, mandado de segurança e habeas data","question":"Qual remédio protege a liberdade de ir e vir?","options":["Mandado de injunção","Habeas corpus","Ação popular","Habeas data"],"answer":1,"why":"HC protege a liberdade de locomoção.","principle":"Habeas corpus protege liberdade de locomoção. Mandado de segurança protege direito líquido e certo não amparado por HC ou HD. Habeas data possibilita conhecer ou retificar informações pessoais em bancos públicos ou de caráter público.","context":"São ferramentas diferentes dentro da mesma caixa de proteção.","example":"Ameaça ilegal de prisão: pense em habeas corpus; dado pessoal incorreto em cadastro público: habeas data.","pitfall":"Não use habeas data como sinônimo de qualquer pedido de documento.","reference":"CF/1988, art. 5º, LXVIII–LXXII"},{"id":"u79","cat":"Direito","title":"CF: direitos do trabalhador e direitos sociais","question":"Qual é direito social previsto no art. 6º?","options":["Nomeação automática em concurso","Livre iniciativa como único direito","Educação","Imunidade penal absoluta"],"answer":2,"why":"Educação integra o rol constitucional de direitos sociais.","principle":"Art. 6º trata dos direitos sociais; art. 7º enumera direitos de trabalhadores urbanos e rurais, observadas exceções e regimes. Não confunda direitos sociais com nacionalidade e direitos políticos.","context":"O Estado reconhece necessidades básicas da vida coletiva.","example":"Educação, saúde, alimentação e moradia constam do catálogo de direitos sociais.","pitfall":"A prova pode trocar um direito social por um princípio tributário.","reference":"CF/1988, arts. 6º e 7º"},{"id":"u80","cat":"Direito","title":"CF: administração pública e concurso","question":"Qual princípio constitucional inclui impessoalidade?","options":["O regimento de cada escola.","O caput do art. 37.","O Código Penal exclusivamente.","O art. 5º apenas em matéria penal."],"answer":1,"why":"A impessoalidade está no LIMPE do art. 37.","principle":"Art. 37 apresenta princípios e disciplina concurso, prazo de validade, cargos em comissão e funções de confiança. Nomeação não decorre automaticamente de aprovação em cadastro de reserva; jurisprudência e edital importam.","context":"Cargo efetivo geralmente exige aprovação em concurso, mas há regras e exceções.","example":"Cargo em comissão destina-se a direção, chefia e assessoramento; não substitui funções comuns de toda repartição.","pitfall":"Não confunda aprovação com posse ou exercício.","reference":"CF/1988, art. 37"},{"id":"u81","cat":"Direito","title":"Direito Administrativo: atos e competência","question":"O elemento que responde “quem pode praticar o ato?” é:","options":["Objeto","Motivo","Competência","Publicidade"],"answer":2,"why":"Competência indica o agente legalmente autorizado.","principle":"Verifique competência, finalidade, forma, motivo e objeto. Competência indica quem pode agir; finalidade atende ao interesse público. Vícios podem gerar invalidação, sempre observadas as normas aplicáveis.","context":"Um ato administrativo é uma decisão pública que precisa seguir regras.","example":"Um servidor sem competência não pode decidir sozinho um assunto reservado ao juiz.","pitfall":"A vontade pessoal do agente não substitui a finalidade legal.","reference":""},{"id":"u82","cat":"Direito","title":"Administração: anulação e revogação","question":"Um ato ilegal deve ser enfrentado, em regra, por:","options":["Anulação","Revogação por gosto","Prorrogação automática","Esquecimento"],"answer":0,"why":"A anulação trata do vício de legalidade.","principle":"Anulação enfrenta ilegalidade. Revogação atua sobre conveniência/oportunidade de ato válido, quando juridicamente possível. Controle judicial de legalidade não equivale à gestão da conveniência da Administração.","context":"Uma coisa é corrigir ilegalidade; outra é alterar uma escolha válida.","example":"Se um ato foi praticado contra lei, estuda-se anulação; se ato válido perdeu utilidade, revogação pode ser considerada.","pitfall":"Nem todo ato admite revogação, e efeitos exigem análise.","reference":""},{"id":"u83","cat":"Direito","title":"Administração: agente público e deveres","question":"Qual comportamento se alinha aos deveres do servidor?","options":["Favorecer amigo no atendimento.","Ocultar documento por interesse pessoal.","Divulgar dados sigilosos sem base legal.","Agir com zelo e observar normas."],"answer":3,"why":"Zelo e observância de regras sustentam o serviço público.","principle":"Servidor estatutário, empregado público e agente político são categorias diferentes. Regras do estatuto disciplinam deveres, proibições, responsabilidades e sanções. Na prova, leia quem praticou o ato e qual dever específico foi violado.","context":"Quem usa recursos do Estado responde a padrões de atuação.","example":"Receber presente indevido em troca de favor pode ter consequências administrativas e penais, conforme o caso.","pitfall":"Nem todo erro administrativo é crime ou improbidade.","reference":"Lei estadual SP 10.261/1968"},{"id":"u84","cat":"Direito","title":"Lei 10.261: posse, exercício e provimento","question":"Qual etapa representa o início efetivo do trabalho?","options":["Inscrição","Publicação do edital","Exercício","Classificação preliminar"],"answer":2,"why":"Exercício é o início do desempenho das atribuições.","principle":"Provimento é a forma de preenchimento. Nomeação designa o candidato; posse formaliza a investidura; exercício é o início efetivo das atividades, conforme prazos legais. O edital e o Estatuto estadual estabelecem requisitos e procedimentos.","context":"Entrar no cargo é uma sequência com etapas diferentes.","example":"Ser nomeado hoje não significa ter começado a trabalhar hoje.","pitfall":"Não confunda data de nomeação, posse e exercício.","reference":"Lei SP 10.261/1968, arts. 1º–86"},{"id":"u85","cat":"Direito","title":"Lei 10.261: licenças e afastamentos","question":"Em licença estatutária, o essencial é conferir:","options":["O costume informal da unidade.","Somente o desejo do servidor.","Hipótese, requisitos e autoridade competente.","A opinião do colega."],"answer":2,"why":"Cada licença tem disciplina legal própria.","principle":"A lei prevê hipóteses, requisitos, prazos e procedimentos para licenças e afastamentos. Identifique motivo, autoridade competente e necessidade de documentação; estude literalmente os dispositivos do edital.","context":"Licença não é folga concedida só pela vontade do servidor.","example":"Uma licença para tratamento de saúde depende de requisitos legais e avaliação quando prevista.","pitfall":"Não generalize o mesmo prazo para todas as modalidades de licença.","reference":"Lei SP 10.261/1968, arts. 171–175 e correlatos previstos"},{"id":"u86","cat":"Direito","title":"Penal: peculato, apropriação e desvio","question":"Peculato por apropriação exige, no núcleo principal:","options":["Somente erro de digitação.","Qualquer opinião política.","Apenas um atraso no expediente.","Posse do bem em razão do cargo e apropriação."],"answer":3,"why":"O vínculo funcional com a posse é decisivo.","principle":"Peculato (CP art. 312) envolve apropriar-se ou desviar dinheiro, valor ou bem móvel, público ou particular, de que o agente tem posse em razão do cargo. Outras modalidades previstas no artigo exigem atenção.","context":"Usar coisa confiada ao cargo como se fosse sua quebra a confiança pública.","example":"Servidor desvia valores sob sua guarda funcional para beneficiar terceiro.","pitfall":"Se não há relação com a posse em razão do cargo, examine outro tipo penal; não force “peculato”.","reference":"CP, art. 312"},{"id":"u87","cat":"Direito","title":"Penal: concussão, corrupção e prevaricação","question":"O servidor EXIGE vantagem indevida por causa do cargo:","options":["Prevaricação apenas","Concussão","Apenas desacato","Abandono de função"],"answer":1,"why":"Exigir é verbo nuclear da concussão.","principle":"Concussão (316): exigir vantagem indevida. Corrupção passiva (317): solicitar/receber vantagem ou aceitar promessa, nos termos legais. Prevaricação (319): retardar, deixar de praticar ou praticar indevidamente ato de ofício para satisfazer interesse ou sentimento pessoal.","context":"Exigir, solicitar, receber e atrasar por interesse próprio são verbos-chave.","example":"“Só libero se me pagar” sugere exigência; “me dá algo?” sugere solicitação.","pitfall":"Contexto e demais elementos do tipo também importam, além do verbo.","reference":"CP, arts. 316–319"},{"id":"u88","cat":"Direito","title":"Penal: falsificação material e ideológica","question":"O documento é formalmente autêntico mas traz declaração falsa relevante:","options":["É sempre falsificação de moeda.","É necessariamente furto.","Não pode haver crime.","Pode configurar falsidade ideológica."],"answer":3,"why":"É o contraste didático entre forma do documento e conteúdo declarado.","principle":"Falsidade material envolve adulterar ou fabricar documento. Falsidade ideológica (299) pode consistir em inserir/deixar de inserir declaração falsa relevante em documento formalmente verdadeiro, nas condições do tipo.","context":"Uma coisa é mudar o papel; outra é mentir no conteúdo verdadeiro do papel.","example":"Documento autêntico em sua forma, mas declaração falsa sobre fato juridicamente relevante: investigue falsidade ideológica.","pitfall":"Nem toda informação imprecisa configura crime; precisa preencher o tipo.","reference":"CP, arts. 297–299"},{"id":"u89","cat":"Direito","title":"Penal: crimes contra a justiça","question":"Quando alguém sabe ser inocente a pessoa a quem atribui crime para provocar investigação, estude:","options":["Peculato","Homicídio culposo","Corrupção passiva","Denunciação caluniosa"],"answer":3,"why":"O art. 339 protege a administração da justiça.","principle":"O edital inclui tipos envolvendo denunciação caluniosa, comunicação falsa, falso testemunho e outros atos contra a administração da justiça. Identifique a conduta e os requisitos legais, inclusive conhecimento da inocência quando exigido.","context":"A própria investigação e a decisão precisam de proteção.","example":"Provocar investigação imputando falsamente crime a pessoa sabidamente inocente pode configurar denunciação caluniosa, observados os elementos do art. 339.","pitfall":"Não confunda notícia equivocada de boa-fé com imputação dolosa.","reference":"CP, art. 339"},{"id":"u90","cat":"Direito","title":"Processo civil: petição inicial e defesa","question":"Qual peça normalmente inicia uma ação civil comum?","options":["Petição inicial","Acórdão","Mandado de prisão","Contestação"],"answer":0,"why":"É o instrumento típico de instauração da demanda.","principle":"Petição inicial apresenta partes, fatos, fundamentos, pedidos e demais requisitos legais. Pode ser necessário emendar. Citação chama o réu; contestação é uma defesa usual. O juiz organiza o processo e decide, conforme regras do CPC.","context":"A ação é uma conversa formal com regras de entrada e resposta.","example":"A petição traz o que se pede; a contestação responde aos argumentos.","pitfall":"Emenda da inicial não equivale a sentença de mérito.","reference":"CPC, arts. 318–343"},{"id":"u91","cat":"Direito","title":"Processo civil: revelia e saneamento","question":"Qual afirmação é correta?","options":["Revelia dispensa toda decisão.","Revelia dá vitória automática sempre.","Revelia só existe em processo penal.","Revelia pode gerar efeitos, mas há exceções."],"answer":3,"why":"O CPC prevê limites e exceções aos efeitos da revelia.","principle":"Revelia decorre, em regra, da ausência de contestação; efeitos sobre alegações de fato dependem das hipóteses legais. Saneamento organiza pontos controvertidos e provas. Leia as exceções antes de concluir que “ganha automaticamente”.","context":"Não responder ao processo pode ter efeitos, mas há exceções.","example":"Réu não contesta; o juiz ainda precisa observar as regras e analisar o caso.","pitfall":"Revelia não significa automaticamente procedência de qualquer pedido.","reference":"CPC, arts. 344–357"},{"id":"u92","cat":"Direito","title":"Processo civil: recursos e prazos","question":"Qual recurso se volta a omissão ou contradição da decisão?","options":["Embargos de declaração","Contestação","Petição inicial","Mandado de levantamento"],"answer":0,"why":"Embargos de declaração têm hipóteses específicas no CPC.","principle":"CPC contém modalidades como apelação, agravo de instrumento e embargos de declaração. Cada uma tem finalidade e pressupostos específicos. Prazos e contagem exigem atenção à regra vigente e a eventuais exceções.","context":"Recurso é pedir nova análise por meio previsto na lei.","example":"Embargos de declaração tratam, em regra, de obscuridade, contradição, omissão ou erro material.","pitfall":"Não conclua que todo recurso suspende automaticamente todos os efeitos.","reference":"CPC, arts. 994–1026"},{"id":"u93","cat":"Direito","title":"Processo civil: tutela provisória","question":"Em regra, tutela de urgência exige:","options":["Sentença definitiva anterior.","Somente pagamento de taxa.","Probabilidade do direito e perigo de dano ou risco ao resultado útil.","Apenas vontade do autor."],"answer":2,"why":"São os requisitos centrais do art. 300.","principle":"Tutela provisória pode ser de urgência ou evidência, conforme requisitos. Na tutela de urgência, atente a probabilidade do direito e perigo de dano ou risco ao resultado útil do processo. Não é julgamento definitivo do mérito.","context":"Quando esperar pode causar dano, a lei prevê decisões provisórias.","example":"Medicamento urgente, com documentos que indiquem plausibilidade e risco, pode justificar análise de tutela de urgência.","pitfall":"Um pedido urgente não é automaticamente deferido; a prova examina os requisitos.","reference":"CPC, art. 300"},{"id":"u94","cat":"Direito","title":"Processo civil: impedimento e suspeição","question":"O objetivo das regras de impedimento e suspeição é:","options":["Acelerar publicidade de anúncios.","Eliminar toda defesa.","Proteger imparcialidade no julgamento.","Substituir o Ministério Público."],"answer":2,"why":"O processo precisa de julgador imparcial.","principle":"Impedimento é hipótese objetiva legal de afastamento do julgador; suspeição trata situações indicadas pelo CPC que comprometem confiança na imparcialidade. O edital inclui artigos sobre o tema.","context":"Quem julga deve ser imparcial, e a lei cria filtros.","example":"Juiz com relação legalmente impeditiva não deve atuar no feito.","pitfall":"Não trate qualquer desagrado de uma parte como suspeição automática.","reference":"CPC, arts. 144–148"},{"id":"u95","cat":"Direito","title":"Processo penal: inquérito e ação penal","question":"Qual afirmação é correta?","options":["Inquérito investiga, e processo permite julgamento com defesa.","Denúncia é decisão condenatória.","Polícia profere sentença penal.","Inquérito sempre termina em condenação."],"answer":0,"why":"As etapas e funções são distintas.","principle":"Inquérito investiga fatos e autoria, sem ser processo de condenação. Ação penal leva a acusação ao Judiciário. Distinga atribuições de polícia, Ministério Público, juiz e defesa.","context":"Investigar não é a mesma coisa que julgar.","example":"Uma investigação pode gerar elementos para decisão de oferecer denúncia, sem significar culpabilidade automática.","pitfall":"Não confunda indiciado com condenado.","reference":""},{"id":"u96","cat":"Direito","title":"Processo penal: citação, intimação e defesa","question":"Qual ato chama formalmente o acusado ao processo?","options":["Sentença","Certidão de trânsito","Citação","Alvará"],"answer":2,"why":"Citação estabelece a ciência formal inicial.","principle":"Citação chama o acusado a integrar a relação processual; intimação comunica atos. Os dispositivos do edital tratam de formas e efeitos, inclusive editalícia quando cabível. A defesa técnica integra o devido processo.","context":"Ninguém deve responder a processo sem meios regulares de saber e defender-se.","example":"Acusado precisa ser regularmente citado; depois, comunicações de atos seguem regras próprias.","pitfall":"Citação por edital não é regra universal nem serve para qualquer situação.","reference":"CPP, arts. 351–372"},{"id":"u97","cat":"Direito","title":"Processo penal: procedimento comum","question":"A instrução processual serve principalmente para:","options":["Determinar punição automática.","Produzir e examinar provas sob regras processuais.","Substituir a sentença por propaganda.","Dispensar contraditório."],"answer":1,"why":"Instrução é fase de produção e avaliação de provas.","principle":"O CPP disciplina recebimento, resposta, instrução, provas, debates e decisão, conforme o procedimento aplicável. Não memorize apenas uma ordem genérica; algumas hipóteses têm regras próprias.","context":"O processo tem sequência e oportunidades de defesa.","example":"Após a acusação, o rito permite defesa e produção de prova antes de eventual condenação.","pitfall":"Não confunda rito ordinário, sumário e procedimentos especiais.","reference":"CPP, arts. 394–405"},{"id":"u98","cat":"Direito","title":"Juizados especiais: simplicidade com limites","question":"Qual é um princípio dos juizados?","options":["Segredo absoluto em todos os casos","Complexidade obrigatória","Simplicidade","Ausência de defesa"],"answer":2,"why":"A Lei 9.099 privilegia simplicidade e celeridade.","principle":"Na Lei 9.099/1995 há oralidade, simplicidade, informalidade, economia processual e celeridade. Distinga área cível de criminal. Competência, valores e causas excluídas precisam de leitura literal.","context":"Juizado busca procedimento mais simples, não ausência de regras.","example":"Pequena demanda cível admissível pode usar rito simplificado.","pitfall":"Nem toda causa ou parte pode tramitar no Juizado.","reference":"Lei 9.099/1995"},{"id":"u99","cat":"Direito","title":"Legislação interna: teletrabalho TJSP","question":"Uma leitura correta da regulamentação é:","options":["Não exige proteção de informações.","Teletrabalho deve observar requisitos e controles previstos.","Dispensa entrega de tarefas.","Basta o desejo pessoal."],"answer":1,"why":"O regime é regulamentado e condicionado.","principle":"Resolução TJSP 850/2021 trata do teletrabalho. Estude requisitos, atividades, acompanhamento, vedações e deveres segundo a redação vigente indicada no edital. A aplicação depende das condições da norma e das determinações administrativas.","context":"Teletrabalho exige regras de produtividade e controle, não liberdade irrestrita.","example":"Um servidor em teletrabalho segue sujeito à produtividade, segurança e rotinas estabelecidas.","pitfall":"Evite imaginar que teletrabalho é direito automático de qualquer servidor.","reference":"Resolução TJSP 850/2021"},{"id":"u100","cat":"Direito","title":"Legislação interna: eproc TJSP","question":"A resolução 963/2025 é sobre:","options":["Crime de peculato.","Regras gerais de acentuação.","Governança e utilização do eproc no TJSP.","Juros simples."],"answer":2,"why":"É norma interna especificamente vinculada ao eproc.","principle":"Resolução TJSP 963/2025 disciplina governança e utilização do eproc. Na preparação, diferencie sistema, unidade responsável, perfis, fluxo processual e regras de segurança conforme texto vigente.","context":"Processo eletrônico é um sistema de trabalho com regras de governança.","example":"Protocolo eletrônico e movimentações precisam seguir perfis e procedimentos autorizados.","pitfall":"Não presuma que eproc e e-SAJ são equivalentes em todas as rotinas.","reference":"Resolução TJSP 963/2025"},{"id":"u101","cat":"Direito","title":"Legislação interna: Corregedoria e cartório","question":"Qual é a principal finalidade das Normas da Corregedoria?","options":["Criar salário dos servidores sem lei.","Eliminar controle documental.","Padronizar e orientar rotinas judiciais conforme normas aplicáveis.","Substituir toda a Constituição."],"answer":2,"why":"As normas estruturam o serviço judiciário.","principle":"As Normas de Serviço da Corregedoria Geral da Justiça regulam atividades e controles de unidades judiciais. O edital delimita Tomo I e seções específicas; estude a organização documental, tramitação, atendimento e procedimentos pelos dispositivos originais.","context":"O balcão do cartório segue um manual de procedimentos.","example":"Cumprir um mandado e certificar atos exigem registro e conferência conforme normas.","pitfall":"Não use resumos como substitutos das seções completas do Tomo I.","reference":"NSCGJ, Tomo I, seções do Anexo VIII"},{"id":"u102","cat":"Lógica","title":"Tabela-verdade: condicional","question":"Quando P→Q é falsa?","options":["P verdadeira e Q verdadeira","P falsa e Q falsa","P verdadeira e Q falsa","P falsa e Q verdadeira"],"answer":2,"why":"Condicional só falha no caso V→F.","principle":"P→Q é falsa somente quando P é verdadeira e Q é falsa. Não confunda “se P então Q” com “se Q então P”. Contrapositiva: ¬Q→¬P.","context":"“Se chover, então molha” só falha se chover e não molhar.","example":"Se a inscrição foi homologada, então o pagamento foi confirmado. Se pagamento não foi confirmado, a contrapositiva nega a homologação, sob essa premissa.","pitfall":"A inversa Q→P não decorre automaticamente.","reference":""},{"id":"u103","cat":"Lógica","title":"Negação de condicional","question":"Negação de “Se foi citado, compareceu”:","options":["Se compareceu, foi citado.","Não foi citado e não compareceu.","Não foi citado e compareceu.","Foi citado e não compareceu."],"answer":3,"why":"A negação é P ∧ ¬Q.","principle":"¬(P→Q) equivale a P e ¬Q. Negar todo condicional não é trocar apenas uma palavra; a condição original precisa ocorrer e a consequência não.","context":"Para negar “se P, então Q”, mostre um caso em que P ocorreu e Q falhou.","example":"“Se estudar, passará” é negada por “Estudou e não passou”.","pitfall":"“Não estudou e passou” não nega o condicional.","reference":""},{"id":"u104","cat":"Lógica","title":"Equivalência: contrapartida lógica","question":"Equivalente a “Se A, então B” é:","options":["A e não B.","Se não B, então não A.","Se não A, então não B.","Se B, então A."],"answer":1,"why":"É a contrapositiva.","principle":"P→Q equivale à contrapositiva ¬Q→¬P e à disjunção ¬P∨Q. Monte casos quando estiver inseguro.","context":"Duas frases podem descrever a mesma regra de modos diferentes.","example":"“Se é servidor do setor, tem crachá” equivale a “Se não tem crachá, não é servidor do setor”, assumindo a premissa dada.","pitfall":"A recíproca Q→P não é equivalente.","reference":""},{"id":"u105","cat":"Lógica","title":"Contagem de possibilidades","question":"3 opções de capa e 2 de fonte geram quantas combinações?","options":["6","5","9","3"],"answer":0,"why":"São 3×2 escolhas combinadas.","principle":"Se há 3 camisetas e 2 calças, o princípio multiplicativo gera 3×2=6 combinações quando todas são possíveis. Condições restritivas exigem excluir casos proibidos.","context":"Organizar casos é melhor do que adivinhar.","example":"Com 2 turnos e 3 locais possíveis, há 6 pares turno-local.","pitfall":"Não multiplique quando as escolhas não são independentes.","reference":""},{"id":"u106","cat":"Matemática","title":"Razão, proporção e escala","question":"Se 3 itens custam R$ 12, quanto custam 5 ao mesmo preço unitário?","options":["R$ 15","R$ 20","R$ 30","R$ 24"],"answer":1,"why":"Cada item custa R$ 4; cinco custam R$ 20.","principle":"Razão a/b compara a com b. Proporção iguala duas razões. Escala 1:100 significa que 1 unidade no desenho corresponde a 100 da realidade, usando unidades coerentes.","context":"Uma razão compara duas quantidades em uma mesma régua.","example":"Se 2 atendentes lidam com 30 solicitações no mesmo período e ritmo, 4 atendentes lidariam com 60, nas hipóteses de proporcionalidade.","pitfall":"Não trate qualquer situação como proporcional sem verificar os dados.","reference":""},{"id":"u107","cat":"Matemática","title":"Equação do 2º grau","question":"As raízes reais de x²−16=0 são:","options":["4 e −4","16 e −16","0 e 16","Só 4"],"answer":0,"why":"x²=16 implica x=±4.","principle":"Na forma ax²+bx+c=0, com a≠0, use fatoração, produto notável ou fórmula quadrática. O discriminante Δ=b²−4ac informa a quantidade de raízes reais.","context":"Uma expressão com x² pode ter até duas soluções reais.","example":"x²−9=0 → (x−3)(x+3)=0 → x=3 ou x=−3.","pitfall":"Não esqueça a raiz negativa quando ela também satisfaz a equação.","reference":""},{"id":"u108","cat":"Matemática","title":"Sistema de equações","question":"Se x+y=8 e x−y=2, x é:","options":["3","5","4","6"],"answer":1,"why":"Somando, 2x=10, x=5.","principle":"Métodos: substituição ou eliminação. Ex.: x+y=10 e x−y=2. Somando: 2x=12, x=6; então y=4. Confira nas duas equações.","context":"Duas pistas juntas permitem descobrir dois números.","example":"6+4=10 e 6−4=2.","pitfall":"Não pare após encontrar apenas uma variável.","reference":""},{"id":"u109","cat":"Matemática","title":"Unidades e volume","question":"O volume de caixa 3 m×2 m×1 m é:","options":["6 m²","6 m³","9 m³","5 m³"],"answer":1,"why":"3×2×1=6, unidade cúbica.","principle":"1 m=100 cm; 1 m²=10.000 cm²; 1 m³=1.000 litros. Para um paralelepípedo, volume = comprimento×largura×altura. Cuidado: ao elevar a unidade, o fator de conversão também é elevado.","context":"Comprimento mede borda; área mede superfície; volume mede espaço.","example":"Caixa 2 m×1 m×1 m ocupa 2 m³.","pitfall":"Não converta m² como se fosse m.","reference":""},{"id":"u110","cat":"Informática","title":"Excel: referências absolutas e mistas","question":"Qual referência fixa a coluna, mas deixa a linha mudar?","options":["$B2","$B$2","B2","B$2"],"answer":0,"why":"O $ antes da letra fixa a coluna.","principle":"A1 muda coluna e linha; $A$1 fixa ambas; $A1 fixa coluna; A$1 fixa linha. Ao copiar fórmula, apenas as partes relativas se deslocam.","context":"O cifrão é uma âncora para a parte que não deve se mover.","example":"=$A2*B$1 de C2 para D3 torna-se =$A3*C$1.","pitfall":"O cifrão não representa dinheiro nesse contexto.","reference":"MS Excel 365"},{"id":"u111","cat":"Informática","title":"Excel: contagem e critérios","question":"Qual função conta células que satisfazem um critério?","options":["HOJE","CONCAT","MÉDIA","CONT.SE"],"answer":3,"why":"CONT.SE faz contagem condicional.","principle":"CONT.SE(intervalo;critério) conta células que cumprem uma condição; SOMASE soma valores correspondentes ao critério; SE devolve resultados diferentes dependendo do teste lógico. Dependendo do idioma/configuração, separadores e nomes mudam.","context":"Fórmulas são pequenos funcionários que executam instruções.","example":"=CONT.SE(A2:A10;\"Atrasado\") conta ocorrências do texto “Atrasado”.","pitfall":"Contar valores e somar valores são operações diferentes.","reference":"MS Excel 365"},{"id":"u112","cat":"Informática","title":"Excel: filtros e formatação condicional","question":"Qual recurso destaca automaticamente vencimentos atrasados?","options":["Formatação condicional","Hiperlink","Somente zoom","Quebra de página"],"answer":0,"why":"Regras de formatação respondem aos valores da célula.","principle":"Classificar reordena, filtrar mostra subconjunto; formatação condicional aplica cor com base em regra. Para vencimentos, combine datas, filtros e fórmulas.","context":"O filtro esconde temporariamente linhas; formatação condicional destaca automaticamente.","example":"Marcar em vermelho datas menores que HOJE() para itens ainda não pagos.","pitfall":"Cor por si só não substitui uma regra correta de dados.","reference":"MS Excel 365"},{"id":"u113","cat":"Informática","title":"Word: estilos e sumário automático","question":"Qual recurso sustenta o sumário automático?","options":["Estilos de títulos","Repetir espaços","Aumentar brilho","Modo avião"],"answer":0,"why":"O sumário identifica a estrutura pelos estilos.","principle":"Aplicar estilos Título 1/2 permite sumário automático consistente. Quebras de página são diferentes de vários Enter. Localizar/Substituir agiliza revisão.","context":"Estilos são etiquetas que dizem quais partes são títulos e subtítulos.","example":"Se “Capítulo 1” usa Título 1, aparece no sumário após atualização.","pitfall":"Digitar títulos manualmente no sumário pode quebrar atualizações.","reference":"MS Word 365"},{"id":"u114","cat":"Informática","title":"Segurança digital: phishing e anexos","question":"Ao receber link suspeito, o melhor é:","options":["Informar a senha imediatamente.","Desativar antivírus.","Compartilhar com todos.","Verificar por canal oficial antes de acessar."],"answer":3,"why":"A conferência independente reduz risco de fraude.","principle":"Verifique endereço, domínio, pedido urgente, anexos e links. Não forneça senhas a páginas suspeitas. Autenticação multifator ajuda a proteger contas, mas não substitui atenção.","context":"Golpe digital costuma vestir roupa de mensagem confiável.","example":"E-mail diz “pague agora” e imita tribunal; confira por canal oficial independente.","pitfall":"Cadeado HTTPS não prova sozinho que a empresa é legítima.","reference":""},{"id":"u115","cat":"Informática","title":"Teams e OneDrive: permissão e versão","question":"Qual permissão permite ler sem modificar o arquivo?","options":["Administrador global","Somente visualização","Proprietário","Edição irrestrita"],"answer":1,"why":"Visualização não concede edição.","principle":"Teams oferece reuniões, canais e colaboração; OneDrive armazena arquivos em nuvem e permite controle de acesso. Diferencie visualizar de editar, sincronizar de criar cópia e histórico de versões de lixeira.","context":"Compartilhar não significa liberar tudo para qualquer pessoa.","example":"Compartilhar documento somente para leitura evita edição indesejada.","pitfall":"Uma pasta na nuvem também pode ter restrições de acesso.","reference":""},{"id":"u116","cat":"Gerais","title":"Atualidades: diferenciar notícia e opinião","question":"Ao estudar uma notícia, o primeiro cuidado é:","options":["Ignorar contexto.","Confirmar data, fonte e fatos.","Confiar em título isolado.","Decorar opinião do comentarista."],"answer":1,"why":"A prova cobra fatos e contexto, não boatos.","principle":"Cheque data, fonte, local, personagens e contexto. Prefira fonte primária para documentos oficiais e mais de uma fonte confiável para temas controversos. Estude fatos a partir do primeiro semestre de 2026, conforme edital.","context":"Duas manchetes podem descrever o mesmo fato de modo diferente.","example":"Uma decisão oficial deve ser localizada no órgão responsável, e notícias ajudam a explicar impactos.","pitfall":"Não memorize boatos ou inferências como fatos confirmados.","reference":"Edital 02/2026, Anexo VIII"},{"id":"u117","cat":"Gerais","title":"LBI: acessibilidade e barreiras","question":"Uma página incompatível com leitor de tela pode gerar barreira:","options":["Tributária","Tecnológica","Somente geográfica","Eleitoral"],"answer":1,"why":"A barreira tecnológica impede acesso a ferramentas e comunicação.","principle":"A LBI define barreiras urbanísticas, arquitetônicas, em transportes, comunicações, atitudes e tecnologia. Estude também igualdade de oportunidades, prioridade e atendimento respeitoso nos artigos exigidos.","context":"Acessibilidade é remover obstáculos para participação de todos.","example":"Sistema digital sem leitor de tela pode criar barreira tecnológica para pessoa com deficiência visual.","pitfall":"Acessibilidade não se resume a rampa.","reference":"Lei 13.146/2015, art. 3º"},{"id":"u118","cat":"Redação","title":"Redação: argumento sem exagero","question":"Qual sequência fortalece um parágrafo?","options":["Afirmação, explicação e exemplo pertinente.","Só adjetivos fortes.","Uma citação sem ligação.","Repetir a tese quatro vezes."],"answer":0,"why":"A relação entre ideias gera argumento.","principle":"Faça a estrutura afirmação → por quê → consequência/ilustração. Prefira exemplos verificáveis e relações coerentes. Não invente estatísticas. Distinga tese de repertório e mantenha o recorte do tema.","context":"Um argumento forte se sustenta com explicação, não com grito.","example":"Tese: acesso digital facilita serviços; explicação: reduz deslocamentos; ressalva: exige acessibilidade.","pitfall":"Uma frase famosa solta não substitui justificativa.","reference":""},{"id":"u119","cat":"Redação","title":"Redação: coesão e revisão","question":"Qual atitude melhora a coesão?","options":["Usar conectivos adequados à relação entre ideias.","Repetir “portanto” em toda frase.","Evitar qualquer referência entre parágrafos.","Trocar assunto sem transição."],"answer":0,"why":"Conectivos precisam expressar relação lógica real.","principle":"Procure pronome sem antecedente, conectivo incoerente, repetição excessiva, frases longas e concordância. Verifique se cada parágrafo faz avançar a tese. Na Vunesp, leia os critérios específicos e evite reproduzir textos da coletânea.","context":"A última leitura é como revisar a mochila antes de sair.","example":"Primeira revisão: conteúdo; segunda: gramática; terceira: legibilidade e pontuação.","pitfall":"Não deixe a redação para o último minuto da prova.","reference":""}];
